import{_ as r,o as e,c as t,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"聊天记录与数据","description":"","frontmatter":{"title":"聊天记录与数据"},"headers":[],"relativePath":"workspace/records.md","filePath":"workspace/records.md","lastUpdated":1787948622000}'),s={name:"workspace/records.md"};function i(n,a,l,c,d,h){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="聊天记录与数据" tabindex="-1">聊天记录与数据 <a class="header-anchor" href="#聊天记录与数据" aria-label="Permalink to &quot;聊天记录与数据&quot;">​</a></h1><p>想知道 AI 到底答得怎么样，看两处：「聊天记录」逐条复盘，「仪表盘 / 数据分析」看整体。桌面客户端的「聊天记录」「数据统计」是同一批数据。</p><h2 id="聊天记录" tabindex="-1">聊天记录 <a class="header-anchor" href="#聊天记录" aria-label="Permalink to &quot;聊天记录&quot;">​</a></h2><p>按平台和顾客组织会话列表，点开可以看完整对话。</p><h3 id="待跟进筛选" tabindex="-1">待跟进筛选 <a class="header-anchor" href="#待跟进筛选" aria-label="Permalink to &quot;待跟进筛选&quot;">​</a></h3><p>列表支持只看<strong>待跟进</strong>的会话——AI 转人工没接上、或 AI 明确处理不了的对话都会进入待跟进。建议每天固定时间清一遍，配合<a href="/aicare-docs/client/notify">通知设置</a>可以做到不漏单。</p><h3 id="会话详情" tabindex="-1">会话详情 <a class="header-anchor" href="#会话详情" aria-label="Permalink to &quot;会话详情&quot;">​</a></h3><p>点开单条会话，除了消息内容还能看到每次回复的过程信息：</p><ul><li><strong>路由说明</strong>：这条消息由哪个接待角色处理、是怎么命中的（默认接待还是触发规则）、用的哪档智能程度。</li><li><strong>参考资料</strong>:AI 引用了知识库里的哪几条内容。</li><li><strong>转接事件</strong>：什么时候转的人工、转给了谁、是否成功。</li></ul><p>回答不对时，先看参考资料：引用错了说明知识库内容有问题，没引用说明知识库缺内容。排查思路见<a href="/aicare-docs/faq/accuracy">回答不准怎么办</a>。</p><h2 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to &quot;仪表盘&quot;">​</a></h2><p>工作台首页级的统计视图：核心接待数据和待处理事项。适合每天扫一眼。</p><h2 id="数据分析" tabindex="-1">数据分析 <a class="header-anchor" href="#数据分析" aria-label="Permalink to &quot;数据分析&quot;">​</a></h2><p>更细的运营数据：</p><ul><li><strong>工具调用次数</strong>：AI 查知识库、查表格、转人工等动作的频次。</li><li><strong>转接对象占比</strong>：人工会话在各客服之间的分布。</li><li><strong>转接成功率</strong>：转人工的接通情况。转接失败多，通常是接待时段客服不在线，考虑调整<a href="/aicare-docs/solution/transfer#离线跟进">离线跟进设置</a>。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>聊天记录保存多久？</strong> 在正常使用期间持续保留，可随时回溯。</p><p><strong>看到某条回复有问题怎么办？</strong> 从会话详情确认原因（知识库错、触发规则错、还是话术问题），再去对应页面修改。改完用<a href="/aicare-docs/solution/test">对话测试</a>验证。</p>',18)])])}const f=r(s,[["render",i]]);export{u as __pageData,f as default};
